// Mask lane names FIRST -- real n8n workflow names can embed client context
// (name prefixes tied to a specific client). Compute a stable pseudonymous
// lane_ref from a deterministic string hash and drop the real name before
// anything downstream can store or render it.

function stableHash(str) {
  // FNV-1a 32-bit, pure JS, no crypto module needed in the n8n sandbox.
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h * 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

const rawItems = $input.all();
const records = [];
for (const item of rawItems) {
  const j = item.json;
  if (j && Array.isArray(j.data)) {
    records.push(...j.data);
  } else {
    records.push(j);
  }
}
const lanes = [];

for (const wf of records) {
  // Sample-mode items already carry a synthetic lane_ref + declared fields --
  // pass them through unmasked (they are synthetic, never real workflow names).
  if (wf.sample_mode === true) {
    lanes.push({
      lane_ref: wf.lane_ref,
      workflow_id: wf.workflow_id || ('sample-' + wf.lane_ref),
      active: wf.active !== false,
      upstream_count_window: wf.upstream_count_window,
      run_count_window: wf.run_count_window,
      last_success_at: wf.last_success_at || null
    });
    continue;
  }

  const realName = String(wf.name || '');
  const hash = stableHash(realName);
  lanes.push({
    lane_ref: 'lane_' + hash.slice(0, 8),
    workflow_id: wf.id,
    active: wf.active === true
    // realName intentionally dropped here -- never stored, never rendered.
  });
}

return [{ json: { lanes } }];

// Evaluate obligation -- decide, per lane, whether an obligation was missed.
// Doctrine (feedback-silence-is-not-failure): a lane can be quiet and healthy
// for three reasons -- no saved successes (unmeasurable), demand-driven with
// no demand (event-driven, 0 upstream), or switched off. None of those three
// may ever produce an incident.

function dedupeByKey(arr, keyFn) {
  const m = new Map();
  for (const r of arr) m.set(keyFn(r), r);
  return [...m.values()];
}

const capsItems = $('Load caps').all();
const caps = capsItems.length ? capsItems[0].json : {};
const killEnabled = caps.kill_enabled === true || caps.kill_enabled === 'true';
const errorTripThreshold = Number(caps.error_trip_threshold != null ? caps.error_trip_threshold : 3);
const consecutiveErrors = Number(caps.consecutive_errors || 0);
const breakerTripped = caps.breaker_tripped === true || caps.breaker_tripped === 'true' ||
  consecutiveErrors >= errorTripThreshold;
const maxIncidentsPerRun = Number(caps.max_incidents_per_run != null ? caps.max_incidents_per_run : 3);
const dryRun = caps.dry_run !== false;

const lanesRaw = $('Mask lane names').first().json.lanes || [];
const expectations = dedupeByKey(
  $('Load expectations').all().map(i => i.json),
  e => e.lane_ref
);
const successRows = dedupeByKey(
  $('Last success per lane').all().map(i => i.json),
  s => s.workflow_id
);

const expByRef = new Map(expectations.map(e => [e.lane_ref, e]));
const successByWid = new Map(successRows.map(s => [String(s.workflow_id), s]));

const nowMs = Date.now();
const runId = $execution.id || ('manual-' + nowMs);
let incidentsThisRun = 0;

const out = [];

for (const lane of lanesRaw) {
  const base = {
    run_id: runId,
    lane_ref: lane.lane_ref,
    workflow_id: lane.workflow_id
  };

  const exp = expByRef.get(lane.lane_ref);
  if (!exp) {
    out.push({ json: { ...base, kind: null, action: 'none', missed: false,
      note: 'no expectation configured for this lane_ref' } });
    continue;
  }

  if (lane.active === false) {
    out.push({ json: { ...base, kind: exp.kind, action: 'none', missed: false,
      note: 'switched off -- off is a decision, not a failure' } });
    continue;
  }

  const succ = successByWid.get(String(lane.workflow_id));
  const lastSuccessAt = succ && succ.last_success_at ? new Date(succ.last_success_at).getTime() : null;
  const runCountWindow = succ ? Number(succ.run_count_window || 0) : 0;
  const upstreamCountWindow = Number(
    lane.upstream_count_window != null ? lane.upstream_count_window
      : (exp.upstream_count_window != null ? exp.upstream_count_window : 0)
  );

  if (exp.kind === 'manual-run') {
    if (lastSuccessAt == null) {
      out.push({ json: { ...base, kind: exp.kind, action: 'reminder_manual', missed: false,
        upstream_count_window: null, run_count_window: runCountWindow,
        last_success_at: null, minutes_since_success: null,
        note: 'manual-run lane never run -- reminder only, never an incident' } });
    } else {
      const minutesSince = (nowMs - lastSuccessAt) / 60000;
      const overdue = minutesSince > Number(exp.expected_interval_min || 0);
      out.push({ json: { ...base, kind: exp.kind,
        action: overdue ? 'reminder_manual' : 'none', missed: false,
        upstream_count_window: null, run_count_window: runCountWindow,
        last_success_at: succ.last_success_at, minutes_since_success: Math.round(minutesSince),
        note: overdue
          ? ('manual-run overdue ' + Math.round(minutesSince) + 'm -- reminder only, never an incident')
          : 'manual-run current' } });
    }
    continue;
  }

  if (exp.kind === 'scheduled') {
    if (lastSuccessAt == null) {
      out.push({ json: { ...base, kind: exp.kind, action: 'none', missed: false,
        upstream_count_window: null, run_count_window: runCountWindow,
        last_success_at: null, minutes_since_success: null,
        note: 'unmeasurable -- no saved success on record, cannot assert silence' } });
      continue;
    }
    const minutesSince = (nowMs - lastSuccessAt) / 60000;
    const missed = minutesSince > Number(exp.expected_interval_min || 0);
    out.push(finishMonitored(base, exp, missed,
      { upstream_count_window: null, run_count_window: runCountWindow,
        last_success_at: succ.last_success_at, minutes_since_success: Math.round(minutesSince) },
      'minutes_since_success=' + Math.round(minutesSince) + ' expected=' + exp.expected_interval_min));
    continue;
  }

  if (exp.kind === 'event-driven') {
    const missed = upstreamCountWindow > 0 && runCountWindow === 0;
    out.push(finishMonitored(base, exp, missed,
      { upstream_count_window: upstreamCountWindow, run_count_window: runCountWindow,
        last_success_at: succ ? succ.last_success_at : null, minutes_since_success: null },
      missed
        ? ('upstream=' + upstreamCountWindow + ' runs=0 -- arrivals with no runs')
        : ('upstream=' + upstreamCountWindow + ' runs=' + runCountWindow + ' -- quiet is not failure here')));
    continue;
  }

  if (exp.kind === 'upstream-count') {
    const missed = runCountWindow < upstreamCountWindow;
    out.push(finishMonitored(base, exp, missed,
      { upstream_count_window: upstreamCountWindow, run_count_window: runCountWindow,
        last_success_at: succ ? succ.last_success_at : null, minutes_since_success: null },
      'upstream=' + upstreamCountWindow + ' runs=' + runCountWindow));
    continue;
  }

  out.push({ json: { ...base, kind: exp.kind, action: 'none', missed: false,
    note: 'unknown kind "' + exp.kind + '" -- refusing to guess, no incident' } });
}

function finishMonitored(base, exp, missed, extra, note) {
  if (!missed) {
    return { json: { ...base, kind: exp.kind, action: 'recover', missed: false, ...extra, note } };
  }
  if (!killEnabled || breakerTripped) {
    return { json: { ...base, kind: exp.kind, action: 'none', missed: true, ...extra,
      note: 'guard blocked: kill_enabled=' + killEnabled + ' breaker_tripped=' + breakerTripped } };
  }
  if (incidentsThisRun >= maxIncidentsPerRun) {
    return { json: { ...base, kind: exp.kind, action: 'none', missed: true, ...extra,
      note: 'guard blocked: max_incidents_per_run(' + maxIncidentsPerRun + ') reached this run' } };
  }
  incidentsThisRun++;
  const dateKey = new Date().toISOString().slice(0, 10);
  return { json: { ...base, kind: exp.kind, action: 'open', missed: true, ...extra, note,
    idempotency_key: 'ep08:' + base.lane_ref + ':' + dateKey,
    dry_run: dryRun } };
}

return out;

// Write whitelist gate -- the ONLY actions this workflow is permitted to turn
// into a write are 'open' (incident upsert) and 'recover' (idempotent close).
// Any other value refuses with a thrown error rather than silently passing
// through or silently dropping the item.

const ALLOWED = new Set(['open', 'recover', 'reminder_manual', 'none']);
const WRITE_ACTIONS = new Set(['open', 'recover']);

const out = [];
for (const item of $input.all()) {
  const action = item.json.action;
  if (!ALLOWED.has(action)) {
    throw new Error(
      'Write whitelist gate: action "' + action + '" is not on the allowlist ' +
      '(open|recover|reminder_manual|none). Refusing to write for lane ' +
      (item.json.lane_ref || 'unknown') + '.'
    );
  }
  if (WRITE_ACTIONS.has(action) && !item.json.lane_ref) {
    throw new Error('Write whitelist gate: a write action arrived with no lane_ref.');
  }
  out.push(item);
}
return out;

// Run summary -- one row per run, plus the full per-lane journal for
// ep08_lane_checks. Built directly off Evaluate obligation's output so the
// summary always matches what Write whitelist gate actually allowed through.

const items = $('Evaluate obligation').all().map(i => i.json);
const caps = $('Load caps').all();
const dryRun = caps.length ? caps[0].json.dry_run !== false : true;
const capsRow = caps.length ? caps[0].json : {};
const breakerTripped = caps.length ? (capsRow.breaker_tripped === true || capsRow.breaker_tripped === 'true' ||
  Number(capsRow.consecutive_errors || 0) >= Number(capsRow.error_trip_threshold != null ? capsRow.error_trip_threshold : 3)) : false;

const runId = items.length ? items[0].run_id : ('manual-' + Date.now());

let missedCount = 0, incidentsOpened = 0, incidentsRecovered = 0, remindersSent = 0, guardBlocked = 0;

for (const it of items) {
  if (it.missed) missedCount++;
  if (it.action === 'open') incidentsOpened++;
  if (it.action === 'recover') incidentsRecovered++;
  if (it.action === 'reminder_manual') remindersSent++;
  if (it.action === 'none' && it.missed) guardBlocked++;
}

const laneChecks = items.map(it => ({
  lane_ref: it.lane_ref,
  kind: it.kind || null,
  expected_interval_min: it.expected_interval_min != null ? it.expected_interval_min : null,
  last_success_at: it.last_success_at || null,
  minutes_since_success: it.minutes_since_success != null ? it.minutes_since_success : null,
  upstream_count_window: it.upstream_count_window != null ? it.upstream_count_window : null,
  run_count_window: it.run_count_window != null ? it.run_count_window : null,
  missed: !!it.missed,
  action: it.action,
  note: it.note || ''
}));

return [{
  json: {
    run_id: runId,
    dry_run: dryRun,
    lanes_evaluated: items.length,
    missed_count: missedCount,
    incidents_opened: incidentsOpened,
    incidents_reminded: 0,
    incidents_recovered: incidentsRecovered,
    reminders_sent: remindersSent,
    guard_blocked: guardBlocked > 0,
    breaker_tripped: breakerTripped,
    lane_checks_json: JSON.stringify(laneChecks)
  }
}];
